# generated by aitest
import os
import tempfile
import tomli


def test_load_file():
    fd, path = tempfile.mkstemp(suffix=".toml")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write('x = 42\nname = "toml"\n')
        with open(path, "rb") as f:
            data = tomli.load(f)
        assert data == {"x": 42, "name": "toml"}
    finally:
        os.remove(path)
